package com.airesumebuilder.feature.pdf.service;
import com.airesumebuilder.feature.analytics.service.UsageMetricService;import com.airesumebuilder.feature.pdf.repository.PdfExportRepository;import java.security.MessageDigest;import java.util.HexFormat;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PdfService{private final PdfExportRepository repository;private final PdfRenderer renderer;private final UsageMetricService metrics;public PdfService(PdfExportRepository repository,PdfRenderer renderer,UsageMetricService metrics){this.repository=repository;this.renderer=renderer;this.metrics=metrics;}@Transactional public GeneratedPdf generate(String email,long resumeId){var resume=repository.resume(email,resumeId);byte[] bytes=renderer.render(resume);String name=safeName(resume.title())+".pdf";repository.record(resume,name,bytes.length,sha(bytes));metrics.increment(UsageMetricService.PDF_EXPORT);return new GeneratedPdf(name,bytes);}@Transactional(readOnly=true)public Page history(String email,long resumeId,int page,int size){repository.resume(email,resumeId);int p=Math.max(0,page),s=Math.min(Math.max(1,size),100);return new Page(repository.history(email,resumeId,s,p*s),p,s,repository.historyCount(email,resumeId));}private String safeName(String value){String result=value==null?"resume":value.replaceAll("[^a-zA-Z0-9._-]+","-").replaceAll("^-|-$","");return result.isBlank()?"resume":result;}private String sha(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception exception){throw new IllegalStateException(exception);}}public record GeneratedPdf(String fileName,byte[]content){}public record Page(List<PdfExportRepository.Export>items,int page,int size,long total){}}
